// Phân tích visitor
const data = $input.first().json;
const ua = (data.user_agent || '').toLowerCase();
const country = (data.country || '').toUpperCase();
const ip = data.ip || '';

const threats = [];

// 1. Kiểm tra quốc gia lạ
const allowedCountries = ['VN', 'LOCAL', '??'];
if (!allowedCountries.includes(country) && country.length === 2) {
  threats.push({
    type: 'foreign_visitor',
    severity: country === 'CN' || country === 'RU' || country === 'KP' ? 'high' : 'medium',
    title: `Visitor từ quốc gia lạ: ${country}`,
    description: `IP ${ip} truy cập từ ${data.city || '?'}, ${country} qua ${data.isp || '?'}`
  });
}

// 2. Kiểm tra bot/scanner
const botPatterns = ['bot', 'scan', 'sqlmap', 'nikto', 'nmap', 'masscan', 'curl', 'wget', 'python-requests', 'hydra', 'metasploit'];
const detectedBot = botPatterns.find(p => ua.includes(p));
if (detectedBot && detectedBot !== 'curl') {
  threats.push({
    type: 'bot_detected',
    severity: detectedBot === 'sqlmap' || detectedBot === 'nikto' || detectedBot === 'nmap' ? 'critical' : 'high',
    title: `Bot/Scanner detected: ${detectedBot}`,
    description: `IP ${ip} sử dụng ${detectedBot} để truy cập ${data.path || '/'}`
  });
}

// 3. Kiểm tra path đáng ngờ
const path = (data.path || '').toLowerCase();
const suspiciousPaths = ['/admin', '/wp-admin', '/.env', '/config', '/backup', '/phpmyadmin', '/.git', '/api/private', '/etc/passwd', '/shell'];
const suspiciousPath = suspiciousPaths.find(p => path.includes(p));
if (suspiciousPath) {
  threats.push({
    type: 'suspicious_path',
    severity: 'high',
    title: `Truy cập path đáng ngờ: ${suspiciousPath}`,
    description: `IP ${ip} truy cập ${path}`
  });
}

// 4. Kiểm tra User-Agent rỗng / bất thường
if (!ua || ua.length < 10) {
  threats.push({
    type: 'suspicious_ua',
    severity: 'medium',
    title: 'User-Agent trống hoặc quá ngắn',
    description: `IP ${ip} không có User-Agent hợp lệ`
  });
}

// Trả về
if (threats.length > 0) {
  return threats.map(t => ({
    json: {
      ip, country, city: data.city, isp: data.isp,
      user_agent: data.user_agent,
      path: data.path,
      threat_type: t.type,
      severity: t.severity,
      title: t.title,
      description: t.description,
      timestamp: data.timestamp || new Date().toISOString(),
      is_suspicious: true
    }
  }));
} else {
  return [{
    json: {
      ip, country, city: data.city, isp: data.isp,
      user_agent: data.user_agent,
      path: data.path,
      threat_type: 'normal',
      severity: 'info',
      title: 'Visitor bình thường',
      description: `IP ${ip} từ ${country}`,
      timestamp: data.timestamp || new Date().toISOString(),
      is_suspicious: false
    }
  }];
}

