// Lấy stats
let stats = { total: 0, critical: 0, high: 0, unique_ips: 0 };
let topIPs = [];

const items = $input.all();
console.log('Input items:', items.length);

// Tìm stats
for (const item of items) {
  const j = item.json;
  if (j.total !== undefined && j.critical !== undefined) {
    stats = j;
    break;
  }
}

// Tìm top IPs (từ tất cả items)
for (const item of items) {
  const j = item.json;
  if (j.ip_address && j.hits !== undefined) {
    topIPs.push(j);
  }
}

// Nếu không có data từ merge, lấy riêng
if (topIPs.length === 0) {
  try {
    const topNode = $('Top 5 IP1').all();
    topIPs = topNode.map(i => i.json).filter(j => j.ip_address);
  } catch (e) {}
}

if (stats.total === 0 && stats.critical === 0) {
  try {
    const statsNode = $('Thống kê 24h1').first();
    if (statsNode && statsNode.json) stats = statsNode.json;
  } catch (e) {}
}

const now = new Date();
let msg = '📊 BÁO CÁO AN NINH 24H\n';
msg += '📅 ' + now.toLocaleDateString('vi-VN') + '\n\n';
msg += '🚨 Tổng alert: ' + (stats.total || 0) + '\n';
msg += '🔴 Critical: ' + (stats.critical || 0) + '\n';
msg += '🟠 High: ' + (stats.high || 0) + '\n';
msg += '🌐 IP độc hại: ' + (stats.unique_ips || 0) + '\n\n';

if (topIPs.length > 0) {
  msg += '🔥 Top 5 IP:\n';
  topIPs.slice(0, 5).forEach((ip, i) => {
    msg += (i + 1) + '. ' + ip.ip_address + ' (' + ip.hits + ' lần)\n';
  });
} else {
  msg += '🔥 Top 5 IP: (không có dữ liệu)';
}

return [{ json: { message: msg } }];

