const t = inp.candidates[0].content.parts[0].text;
const dt = (t.match(/DIEN_TICH:\s*(.+?)(?=\n|$)/)||[])[1]||'Khong xac dinh';
const ms = (t.match(/MAU_SAC:\s*(.+?)(?=\n|$)/)||[])[1]||'Khong xac dinh';
const md = (t.match(/MAT_DO:\s*(.+?)(?=\n|$)/)||[])[1]||'Khong xac dinh';
const tt = (t.match(/TINH_TRANG:\s*(.+?)(?=\n|$)/)||[])[1]||'Khong xac dinh';
const bt = (t.match(/BAT_THUONG:\s*(.+?)(?=\n|$)/)||[])[1]||'khong co';
const kn = (t.match(/KHUYEN_NGHI:\s*(.+?)(?=\n|$)/)||[])[1]||'';
return [{json:{field_id:s.field_id,field_name:s.field_name,dien_tich:dt.trim(),mau_sac:ms.trim(),mat_do:md.trim(),tinh_trang:tt.trim(),bat_thuong:bt.trim(),khuyen_nghi:kn.trim(),ai_full:t}}];

let alerts = [];
let threats = [];
let investigations = [];

try { alerts = $('Get New Alerts').all().map(i => i.json); } catch (e) { alerts = []; }
try { threats = $('Get Watching Threats').all().map(i => i.json); } catch (e) { threats = []; }
try { investigations = $('Get Open Investigations').all().map(i => i.json); } catch (e) { investigations = []; }

const bySeverity = {};
alerts.forEach(a => {
  const s = a.severity || 'unknown';
  bySeverity[s] = (bySeverity[s] || 0) + 1;
});

const byIP = {};
alerts.forEach(a => {
  if (a.ip_address) byIP[a.ip_address] = (byIP[a.ip_address] || 0) + 1;
});
const topIPs = Object.entries(byIP)
  .map(([ip, count]) => ({ ip, count }))
  .sort((a, b) => b.count - a.count)
  .slice(0, 5);

const alertSummary = alerts.slice(0, 20).map(a => 
  `- [${a.severity || 'N/A'}] ${a.title || 'Alert'} | IP: ${a.ip_address || 'N/A'}`
).join('\n') || 'Không có alert mới';

const threatSummary = threats.map(t => 
  `- ${t.threat_type || 'Threat'} từ ${t.ip_address || 'N/A'} (${t.country || 'N/A'}) | ${t.hits || 0} hits`
).join('\n') || 'Không có threat';

const investigationSummary = investigations.map(i => 
  `- [${i.severity || 'N/A'}] ${i.code || 'INV'}: ${i.title || 'N/A'} | Progress: ${i.progress || 0}%`
).join('\n') || 'Không có investigation';

return [{
  json: {
    time_window: '1h',
    alert_count: alerts.length,
    threats_count: threats.length,
    investigations_count: investigations.length,
    by_severity: bySeverity,
    top_ips: topIPs,
    alerts_text: alertSummary,
    threats_text: threatSummary,
    investigations_text: investigationSummary
  }
}];

const response = $json;
const agg = $('Aggregate Data').item.json;

// Lấy text từ Gemini
const text = response?.candidates?.[0]?.content?.parts?.[0]?.text || '';

// Log để debug
console.log('=== GEMINI RAW TEXT ===');
console.log(text.substring(0, 500));

// Clean markdown
let jsonText = text
  .replace(/```json\s*/gi, '')
  .replace(/```\s*/g, '')
  .trim();

// Tìm JSON
let parsed = {};
const start = jsonText.indexOf('{');
const end = jsonText.lastIndexOf('}');

if (start !== -1 && end > start) {
  try {
    parsed = JSON.parse(jsonText.substring(start, end + 1));
    console.log('=== PARSE OK ===');
    console.log(JSON.stringify(parsed).substring(0, 300));
  } catch (e) {
    console.log('=== PARSE ERROR ===', e.message);
    parsed = {};
  }
} else {
  console.log('=== NO JSON FOUND ===');
}

return [{
  json: {
    time_window: agg.time_window,
    alert_count: agg.alert_count,
    threats_count: agg.threats_count,
    investigations_count: agg.investigations_count,
    summary: parsed.summary || 'Không có summary từ AI',
    top_threat: parsed.top_threat || { type: 'N/A', ip: 'N/A', severity: 'medium', description: 'Không có' },
    affected_targets: parsed.affected_targets || [],
    recommendation: parsed.recommendation || 'Không có khuyến nghị',
    risk_level: parsed.risk_level || 'medium'
  }
}];

